-- Advanced extension. Import AFTER schema.sql, marketplace_modules.sql and operations_upgrade.sql.
USE royal_market_place;
CREATE TABLE IF NOT EXISTS themes (id INT AUTO_INCREMENT PRIMARY KEY, theme_key VARCHAR(60) UNIQUE NOT NULL, title VARCHAR(100) NOT NULL, settings JSON NULL, is_active TINYINT(1) DEFAULT 0) ENGINE=InnoDB;
INSERT IGNORE INTO themes(theme_key,title,settings) VALUES
('royal-orange','Royal Orange','{"primary":"#f36b21","layout":"modern"}'),('royal-blue','Royal Blue','{"primary":"#1769aa"}'),('royal-green','Royal Green','{"primary":"#16834a"}'),('royal-purple','Royal Purple','{"primary":"#7042a5"}'),('royal-red','Royal Red','{"primary":"#c62828"}'),('royal-dark','Royal Dark','{"primary":"#e87932","mode":"dark"}'),('royal-minimal','Minimal','{"primary":"#333333"}'),('royal-luxe','Luxury','{"primary":"#a78342"}'),('royal-fashion','Fashion','{"primary":"#d94f8a"}'),('royal-tech','Technology','{"primary":"#1677c8"}'),('royal-grocery','Grocery','{"primary":"#4a9b45"}'),('royal-electronics','Electronics','{"primary":"#2457a7"}'),('royal-pink','Pink','{"primary":"#d65a91"}'),('royal-teal','Teal','{"primary":"#008b8b"}'),('royal-gold','Gold','{"primary":"#b58b28"}'),('royal-slate','Slate','{"primary":"#526273"}'),('royal-coral','Coral','{"primary":"#ef6654"}'),('royal-indigo','Indigo','{"primary":"#3949ab"}'),('royal-sand','Sand','{"primary":"#b38a65"}'),('royal-mono','Monochrome','{"primary":"#222222"}');
CREATE TABLE IF NOT EXISTS translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, locale VARCHAR(10) NOT NULL, translation_key VARCHAR(160) NOT NULL, translation_value TEXT NOT NULL, UNIQUE KEY uq_translation(locale,translation_key)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, image_url VARCHAR(1000) NOT NULL, sort_order INT DEFAULT 0, alt_text VARCHAR(255), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, sku VARCHAR(100) UNIQUE, variant_name VARCHAR(160), attributes JSON NULL, price DECIMAL(12,2) NOT NULL, stock INT NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS seller_payouts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, seller_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, currency CHAR(3) DEFAULT 'PKR', status ENUM('pending','approved','paid','rejected') DEFAULT 'pending', reference VARCHAR(180), requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, processed_at DATETIME NULL, FOREIGN KEY(seller_id) REFERENCES sellers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS shipping_zones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, zone_name VARCHAR(120) NOT NULL, city VARCHAR(100), fee DECIMAL(12,2) NOT NULL DEFAULT 0, free_shipping_min DECIMAL(12,2) NULL, is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS social_post_queue (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, platform VARCHAR(40) NOT NULL, caption TEXT, media_url VARCHAR(1000), scheduled_at DATETIME NULL, status ENUM('draft','queued','published','failed') DEFAULT 'draft', provider_post_id VARCHAR(190), error_text TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS marketing_campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, channel VARCHAR(40), content TEXT, starts_at DATETIME NULL, ends_at DATETIME NULL, status VARCHAR(30) DEFAULT 'draft', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS two_factor_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, code_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS integration_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(60) NOT NULL UNIQUE, is_enabled TINYINT(1) DEFAULT 0, public_config JSON NULL, secret_reference VARCHAR(190) NULL, last_tested_at DATETIME NULL, status VARCHAR(30) DEFAULT 'not_configured') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS email_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, template_key VARCHAR(80) UNIQUE NOT NULL, subject VARCHAR(255), body_html LONGTEXT, is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_webhook_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(60), event_id VARCHAR(190), signature_valid TINYINT(1) DEFAULT 0, response_code INT, payload JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(provider,event_id)) ENGINE=InnoDB;
ALTER TABLE users ADD COLUMN IF NOT EXISTS two_factor_enabled TINYINT(1) NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS two_factor_secret VARCHAR(255) NULL;
